#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MatchTier { Exact, Any, EndpointPrefix, RoutePrefix, BaseFold, Suffix }
impl MatchTier {
    /// Confidence ceiling for the tier. Exact/Any keep today's behaviour
    /// (`weakest(endpoint, route)`); the fuzzy tiers are floored so a consumer
    /// can tell a principled pairing from a guessed one.
    fn ceiling(self) -> Confidence { match self {
        MatchTier::Exact | MatchTier::Any | MatchTier::EndpointPrefix => Confidence::Strong,
        MatchTier::RoutePrefix | MatchTier::BaseFold => Confidence::Medium,
        MatchTier::Suffix => Confidence::Weak } }
}
#[derive(Default)] struct HttpMatchStats { routes: usize, endpoints: usize, paired: usize,
    exact: usize, any: usize, eprefix: usize, rprefix: usize, base: usize, suffix: usize }
```

