```rust
fn api_prefixes() -> Vec<String> {  // GLIA_API_PREFIXES="api,v1,gateway" overrides the default
    match std::env::var("GLIA_API_PREFIXES") {
        Ok(s) if !s.trim().is_empty() => s.split(',').map(|p| p.trim().trim_matches('/').to_ascii_lowercase()).filter(|p| !p.is_empty()).collect(),
        _ => API_PREFIXES.iter().map(|s| (*s).to_string()).collect(),
    }
}
```
