const GRPC_CONTEXT_NEEDLES: &[&str] = &[
    "google.golang.org/grpc", "grpc.Dial", "grpc.NewClient", "io.grpc",
    "@grpc/grpc-js", "Grpc.Net.Client", "GrpcChannel", "import grpc",
    "grpc.aio", "grpc.insecure_channel", "_pb2_grpc", "tonic::",
];
