```rust
/// Decorator nouns the resolver extractor mints as GRAPHQL_RESOLVER nodes
/// (graphql.rs:21-33). They name a root TYPE, never a field, so nothing may
/// key off them — matching against `Query` is what made every `useQuery`
/// call site pair with every resolver file.
const GQL_TYPE_LEVEL: &[&str] =
    &["query", "mutation", "subscription", "resolver", "resolvefield",
      "objecttype", "strawberry", "graphene", "type"];

/// Reduce an operation or resolver name to the FIELD it names, or None when
/// it names no field at all.
fn gql_key(raw: &str) -> Option<String> {
    // `useQuery` -> strip the hook prefix only when the remainder is
    // capitalised, so a real field named `users` survives intact.
    let stripped = raw.strip_prefix("use")
        .filter(|r| r.chars().next().is_some_and(char::is_uppercase))
        .unwrap_or(raw);
    let mut s = stripped.to_lowercase();
    if GQL_TYPE_LEVEL.contains(&s.as_str()) { return None; }
    for suf in ["query", "mutation", "subscription"] {
        if let Some(t) = s.strip_suffix(suf)
            && t.len() >= 3
        { s = t.to_string(); break; }
    }
    let s = s.trim_matches(|c| c == '_' || c == '-').to_string();
    (s.len() >= 3).then_some(s)
}

fn names_match_graphql(operation: &str, resolver: &str) -> bool {
    match (gql_key(operation), gql_key(resolver)) {
        (Some(a), Some(b)) => a == b,
        _ => false,
    }
}
```

