```rust
/// Path segments, lowercased, empties dropped. `"/ws"` and `"ws"` both
/// reduce to `["ws"]`; `"wss://h/a/b"` has already been stripped to `/a/b`
/// by normalise_ws_path (websocket.rs:128-135).
fn ws_segments(s: &str) -> Vec<String> {
    s.trim_matches('/').to_lowercase().split('/')
        .filter(|x| !x.is_empty()).map(String::from).collect()
}

fn ws_paths_match(client: &str, handler: &str) -> bool {
    let c = ws_segments(client);
    let h = ws_segments(handler);
    if c.is_empty() || h.is_empty() { return false; }
    if c == h { return true; }
    // Segment-boundary suffix in either direction: a client mounted at
    // `/api/v1/chat` still reaches a handler registered as `/chat`, but
    // `/news` no longer "ends with" a handler named `ws`.
    let (long, short) = if c.len() >= h.len() { (&c, &h) } else { (&h, &c) };
    long.ends_with(short.as_slice())
}
```

