// CamelCase conventions: JUnit/xUnit/NUnit `FooTest`/`FooTests`,
// ScalaTest/RSpec-for-Scala `FooSpec`, XCTest `FooTests`, JUnit `FooTestCase`,
// and the prefix form `TestFoo`. Matched case-SENSITIVELY on the capital so a
// production name like `Fastest` or `Manifest` can never strip.
const CAMEL_SUFFIXES: [&str; 5] = ["TestCase", "Tests", "Test", "Specs", "Spec"];
for suffix in CAMEL_SUFFIXES {
    if let Some(stem) = name.strip_suffix(suffix)
        && !stem.is_empty()
        && stem.chars().next().is_some_and(char::is_uppercase)
    {
        return stem;
    }
}
if let Some(rest) = name.strip_prefix("Test")
    && rest.chars().next().is_some_and(char::is_uppercase)
{
    return rest;
}
name
```
