```rust
/// Grep-able fired-on counters for dependency-injection extraction. Parsers
/// call `record` each time they push an INJECTS `UnresolvedRef`; the engine
/// calls `flush_marker` once per repo build. Diagnostics only — nothing here
/// ever reaches the graph, the store, or any ordering decision.
pub mod di_stats {
    use std::sync::atomic::{AtomicUsize, Ordering};

    #[derive(Copy, Clone, Debug, PartialEq, Eq)]
    #[repr(usize)]
    pub enum DiShape {
        TsCtor = 0,
        TsInjectFn = 1,
        TsNestCtor = 2,
        JavaCtor = 3,
        JavaField = 4,
        JavaLombok = 5,
        JavaJsr330 = 6,
        CsCtor = 7,
        CsPrimaryCtor = 8,
        CsFromServices = 9,
        PyFastapiDepends = 10,
        PhpCtor = 11,
        GoProvider = 12,
        ScalaCtor = 13,
    }

    /// Wire-format token per shape. Order MUST match the discriminants above;
    /// the unit test asserts it.
    const NAMES: [&str; 14] = [
        "ts-ctor", "ts-inject-fn", "ts-nest-ctor",
        "java-ctor", "java-field", "java-lombok", "java-jsr330",
        "csharp-ctor", "csharp-primary-ctor", "csharp-fromservices",
        "py-fastapi-depends", "php-ctor", "go-provider", "scala-ctor",
    ];

    static COUNTS: [AtomicUsize; NAMES.len()] =
        [const { AtomicUsize::new(0) }; NAMES.len()];

    pub fn record(shape: DiShape) {
        COUNTS[shape as usize].fetch_add(1, Ordering::Relaxed);
    }

    /// Emit one line naming every shape with a non-zero count, then reset.
    /// Resetting matters: a long-lived process (neuropil) or a test that
    /// builds twice (engine/tests/byte_identical.rs) must not accumulate.
    pub fn flush_marker() {
        let mut parts: Vec<String> = Vec::new();
        for (i, name) in NAMES.iter().enumerate() {
            let n = COUNTS[i].swap(0, Ordering::Relaxed);
            if n > 0 {
                parts.push(format!("{name}={n}"));
            }
        }
        if !parts.is_empty() {
            eprintln!("[di] injects refs: {}", parts.join(" "));
        }
    }

    /// Test-only read-and-reset of one slot.
    #[doc(hidden)]
    pub fn take_for_test(shape: DiShape) -> usize {
        COUNTS[shape as usize].swap(0, Ordering::Relaxed)
    }
}
```

