```rust
/// Explicit DI-container registration — the only AST-visible dependency-
/// injection signal in Go. `wire.Build(NewA, NewB)` / `wire.NewSet(...)` /
/// `fx.Provide(...)` / `fx.Invoke(...)` / `fx.Supply(...)` / `dig.Provide(...)`
/// name their providers as bare function identifiers, which are arguments, not
/// calls — so `classify_call` never sees them. Emits INJECTS from the enclosing
/// injector function to each provider.
///
/// Honest scope: this is registration, not consumer->service. Go's idiomatic
/// `func NewX(dep *Dep) *X` constructor cannot be recognised without return-type
/// inference (area A6); no attempt is made here.
fn try_detect_go_provider_set(call: TsNode, src: &[u8], from: NodeId, module_id: NodeId, acc: &mut Acc) {
    const CONTAINERS: [&str; 3] = ["wire", "fx", "dig"];
    const REGISTRARS: [&str; 6] = ["Build", "NewSet", "Provide", "Invoke", "Supply", "Populate"];
    let Some(func) = call.child_by_field_name("function") else { return; };
    if func.kind() != "selector_expression" { return; }
    let (Some(operand), Some(field)) = (func.child_by_field_name("operand"), func.child_by_field_name("field")) else { return; };
    if operand.kind() != "identifier" { return; }
    if !CONTAINERS.contains(&text_of(operand, src)) { return; }
    if !REGISTRARS.contains(&text_of(field, src)) { return; }
    let Some(args) = call.child_by_field_name("arguments") else { return; };
    let mut c = args.walk();
    for a in args.named_children(&mut c) {
        // `NewUserService` (same package) or `repo.NewUserRepo` (imported).
        let name = match a.kind() {
            "identifier" => text_of(a, src).to_string(),
            "selector_expression" => match a.child_by_field_name("field") {
                Some(f) => text_of(f, src).to_string(),
                None => continue,
            },
            _ => continue,   // nested wire.Bind / struct literals: skipped
        };
        acc.refs.push(UnresolvedRef {
            from,
            from_module: module_id,
            qualifier: CallQualifier::Bare(name),
            category: edge_category::INJECTS,
        });
        di_stats::record(DiShape::GoProvider);
    }
}
```

