```rust
// A live METHOD makes its owning type live. DEFINES stays out of
// blast_carry_edges (graph/src/lib.rs:2166) — pulling in a whole container is
// exactly the impact fan-out that list exists to prevent — but liveness is a
// different question: a controller whose action is route-reachable is not dead
// code, and it is the CLASS (not the METHOD) that owns the INJECTS edges to
// its services. Walks UP only, never down, so no container fan-out.
if kind_of(node) == Some(node_kind::METHOD)
    && let Some(&owner) = parent_of.get(&node)
    && matches!(kind_of(owner), Some(k) if k == node_kind::CLASS || k == node_kind::STRUCT || k == node_kind::INTERFACE)
    && live.insert(owner)
{
    queue.push_back(owner);
}
```

