```python
def _materialize(fixture_dir, key):
    created = []
    spec = key.get("materialize") or {}
    for dest_rel, src_rel in sorted(spec.items()):
        dest = (fixture_dir / dest_rel).resolve()
        src = (fixture_dir / src_rel).resolve()
        root = fixture_dir.resolve()
        if root not in dest.parents or root not in src.parents:
            raise ValueError(f"{fixture_dir.name}: materialize path escapes fixture dir: {dest_rel}")
        if not src.exists():
            raise ValueError(f"{fixture_dir.name}: materialize source missing: {src_rel}")
        if dest.exists():
            raise ValueError(f"{fixture_dir.name}: materialize destination already exists: {dest_rel}")
        dest.parent.mkdir(parents=True, exist_ok=True)
        if src.is_dir():
            shutil.copytree(src, dest)
        else:
            shutil.copyfile(src, dest)
        created.append(dest)
    if created:
        print(f"[materialize] {len(created)} paths in {fixture_dir.name}", file=sys.stderr)
    return created
```

