use ignore::gitignore::{Gitignore, GitignoreBuilder};

/// Stack of per-directory `.gitignore` matchers, outermost first. git's rule:
/// the DEEPEST `.gitignore` that matches decides, and a whitelist (`!pat`) in
/// that layer wins over an ignore in an outer one.
#[derive(Default)]
pub struct IgnoreStack {
    layers: Vec<Gitignore>,
    /// `.gitignore` files successfully loaded — the marker's `files` count.
    pub files: usize,
    /// Total ignore+whitelist globs across all loaded files.
    pub patterns: usize,
    /// Files (not dirs) skipped because a pattern matched them.
    pub skipped_files: usize,
}

impl IgnoreStack {
    /// Push `dir`'s own `.gitignore` if it has one. Returns true when a layer
    /// was pushed — the caller MUST `pop()` after descending.
    pub fn push_dir(&mut self, dir: &Path) -> bool {
        let gi_path = dir.join(".gitignore");
        if !gi_path.is_file() { return false; }
        let mut b = GitignoreBuilder::new(dir);
        if let Some(e) = b.add(&gi_path) {
            eprintln!("[walk] warning: {}: {e}", gi_path.display());
            return false;
        }
        match b.build() {
            Ok(gi) => {
                self.files += 1;
                self.patterns += gi.num_ignores() as usize + gi.num_whitelists() as usize;
                self.layers.push(gi);
                true
            }
            Err(e) => { eprintln!("[walk] warning: {}: {e}", gi_path.display()); false }
        }
    }
    pub fn pop(&mut self) { self.layers.pop(); }
    pub fn is_ignored(&self, path: &Path, is_dir: bool) -> bool {
        for gi in self.layers.iter().rev() {
            let m = gi.matched_path_or_any_parents(path, is_dir);
            if m.is_whitelist() { return false; }
            if m.is_ignore() { return true; }
        }
        false
    }
    /// `gitignore 2 files, 4 patterns, skipped 1 files`
    pub fn marker(&self) -> String;
}
```
Every fallible path logs and degrades to "not ignored" — no unwrap, no panic; a malformed `.gitignore` must never sink a build.

