/// Manifest basename (or extension) -> ecosystem, in precedence order. The
/// first entry present in a directory decides the ecosystem; ties never happen
/// because the table is scanned in order.
pub const MANIFESTS: &[(&str, &str)] = &[
    ("package.json", "npm"), ("go.mod", "go"), ("Cargo.toml", "cargo"),
    ("pyproject.toml", "python"), ("setup.py", "python"), ("setup.cfg", "python"),
    ("pom.xml", "maven"), ("build.gradle", "gradle"), ("build.gradle.kts", "gradle"),
    ("pubspec.yaml", "dart"), ("mix.exs", "elixir"), ("composer.json", "php"),
    ("Gemfile", "ruby"), ("Package.swift", "swift"), ("CMakeLists.txt", "cmake"),
    ("build.sbt", "sbt"), ("deps.edn", "clojure"), ("project.clj", "clojure"),
];
/// Extension-keyed manifests (.NET), checked after MANIFESTS.
pub const MANIFEST_EXTS: &[(&str, &str)] = &[("sln", "dotnet"), ("csproj", "dotnet"), ("fsproj", "dotnet"), ("vbproj", "dotnet")];

/// Scan one directory's already-listed entry names. `names` MUST be the sorted
/// file names the walker collected, so detection is deterministic and costs no
/// extra read_dir. Returns None for an ordinary source directory.
pub fn detect(names: &[String]) -> Option<(&'static str, String)>;  // (ecosystem, manifest_basename)

/// Best-effort human label from a manifest's TEXT. Never fails; caller falls
/// back to the directory basename.
pub fn manifest_label(manifest_basename: &str, text: &str) -> Option<String>;
```
