```rust
/// Joins services that declare the SAME message contract (proto message, Avro
/// record) by indexing MESSAGE_TYPE nodes on their full qname
/// (`message:<flavor>:<name>`) and pairing nodes that live in different repos.
/// Mirrors DbResolver; the flavor segment keeps `message:proto:User` and
/// `message:avro:User` apart.
pub struct MessageSchemaResolver;
impl CrossGraphResolver for MessageSchemaResolver {
    fn resolve(&self, merged: &mut MergedGraph) {
        let mut index: HashMap<String, Vec<(NodeId, RepoId, Confidence)>> = HashMap::new();
        for g in &merged.graphs {
            for n in &g.nodes {
                if g.nav.kind_by_id.get(&n.id) != Some(&node_kind::MESSAGE_TYPE) { continue }
                let Some(q) = g.nav.qname_by_id.get(&n.id) else { continue };
                index.entry(q.clone()).or_default().push((n.id, g.repo, n.confidence));
            }
        }
        let (mut types, mut pairs) = (index.len(), 0usize);
        // deterministic: iterate the index by sorted key, not HashMap order
        let mut keys: Vec<&String> = index.keys().collect();
        keys.sort_unstable();
        for k in keys {
            let refs = &index[k];
            if refs.len() < 2 { continue }
            if refs.iter().map(|(_, r, _)| *r).collect::<HashSet<_>>().len() < 2 { continue }
            for i in 0..refs.len() { for j in (i+1)..refs.len() {
                if refs[i].1 == refs[j].1 { continue }
                merged.cross_edges.push(Edge { from: refs[i].0, to: refs[j].0,
                    category: edge_category::SHARES_SCHEMA,
                    confidence: weakest(refs[i].2, refs[j].2) });
                pairs += 1;
            }}
        }
        if types > 0 { eprintln!("[schema-link] message_types={types} pairs={pairs}"); }
    }
}
```
The sorted-key iteration is the determinism guard (audit 2026-06-10 #6 territory); post_passes sorts cross_edges afterwards anyway, but the count and any future per-edge cell must not depend on HashMap order. Same-repo duplicates are skipped exactly as DbResolver/SharedSchemaResolver do.

