Registry: RPC_CALLS = EdgeCategoryId(33) + ALL entry, doc comment naming it 'RPC_CALL → RPC_PROCEDURE; tRPC today, Connect/Twirp when those land'.

```rust
/// Pairs an RPC client call to the procedure it names. Exact match on the
/// procedure path (`<router>.<procedure>`) — deliberately NOT the bidirectional
/// substring rule GraphQLStackResolver uses, which pairs `usequery` to `query`.
pub struct RpcStackResolver;
impl CrossGraphResolver for RpcStackResolver {
    fn resolve(&self, merged: &mut MergedGraph) {
        let index = build_kind_index(&merged.graphs, node_kind::RPC_PROCEDURE, "rpc:");
        if index.is_empty() { return; }
        let (mut calls, mut paired) = (0usize, 0usize);
        for g in &merged.graphs {
            for n in &g.nodes {
                if g.nav.kind_by_id.get(&n.id) != Some(&node_kind::RPC_CALL) { continue }
                let Some(q) = g.nav.qname_by_id.get(&n.id) else { continue };
                let Some(pathname) = q.strip_prefix("rpc_call:") else { continue };
                calls += 1;
                let Some(targets) = index.get(pathname) else { continue };
                paired += 1;
                for t in targets {
                    merged.cross_edges.push(Edge { from: n.id, to: t.id,
                        category: edge_category::RPC_CALLS,
                        confidence: weakest(n.confidence, t.confidence) });
                }
            }
        }
        if calls > 0 { eprintln!("[trpc-link] calls={calls} paired={paired}"); }
    }
}
```
